
/* ============================================================================
   Rondo — arquitectura

   - Una sola IIFE, modo estricto.
   - El estado vive en un objeto APP (auditable y consistente).
   - Las funciones se declaran una sola vez; cero warnings de ESLint.
   - Sin emojis: solo Unicode (◉ ◎ × △ ◆ ◇ ✓ ⚑ ⌖ ⧗ ↻ ⇩ ⌂ ↦ ↤ ⓘ ▂▄▆█ ☾ ☼ ⎘ ⌫ ⤢ ⤡ ⚙).
   - Reentrante: si la API de Wialon no está lista, avisa y reintenta.
   ============================================================================ */

'use strict';
    /* ============================== SECTOR BASE ==============================
     * Contexto/peticiones, migracion, iconos, idioma, version, almacenamiento,
     * valores por defecto, utilidades, estado (APP), helpers de DOM y API de
     * Wialon.
     *
     * Todo el script comparte un UNICO ambito (los @require se concatenan),
     * asi que estos identificadores estan disponibles para el resto de partes.
     * No renombrar ni eliminar sin revisar quien los usa.
     * ====================================================================== */
    /* ====================== CONTEXTO Y PETICIONES ======================
     * Desde la 5.12.2 el script declara @grant GM_xmlhttpRequest para poder
     * llamar a las APIs de IA (que no mandan cabeceras CORS) sin que el
     * navegador corte la peticion. Con ese grant el script corre en el
     * sandbox del gestor de userscripts, asi que:
     *
     *   - La API de Wialon (global `wialon`) vive en el window REAL de la
     *     pagina. La tomamos de `unsafeWindow` cuando exista (Tampermonkey y
     *     Violentmonkey lo exponen con grants) y caemos a `window`.
     *   - `window.localStorage`/`document`/etc. siguen funcionando porque el
     *     sandbox los proxea.
     *
     * `httpRequest()` usa GM_xmlhttpRequest si esta disponible (salta CORS y
     * CSP) y cae a `fetch` si no (por ejemplo con @grant none en algun
     * gestor que no lo exponga).
     */
    const PAGE = (typeof unsafeWindow !== 'undefined' && unsafeWindow) ? unsafeWindow : window;

    function gmXhr() {
        try {
            if (typeof GM_xmlhttpRequest === 'function') return GM_xmlhttpRequest;
            if (typeof GM !== 'undefined' && GM && typeof GM.xmlHttpRequest === 'function') return GM.xmlHttpRequest.bind(GM);
        } catch (_) { /* noop */ }
        return null;
    }
    // Peticion HTTP unificada. Devuelve Promise<{ok, status, texto, red?}>.
    // `red:true` marca fallo de red/CORS (sin respuesta del servidor) y
    // `timeout:true` distingue el corte por tiempo del resto de fallos.
    function httpRequest(opts) {
        const url = opts && opts.url;
        // Sin URL no hay peticion posible. Resolver como fallo en vez de
        // dejar que `opts.url` lance y rompa el `await` del llamador.
        if (!url) return Promise.resolve({ ok: false, status: 0, texto: 'URL vacia', red: true });
        const metodo = (opts && opts.method) || 'GET';
        const headers = (opts && opts.headers) || {};
        const body = opts && opts.body;
        const timeoutMs = Math.max(2000, (opts && opts.timeoutMs) || 25000);
        const gm = gmXhr();
        if (gm) {
            return new Promise((resolve) => {
                let listo = false;
                let safety = null;
                // Resolucion unica: el callback del gestor y el temporizador
                // de seguridad pueden competir; gana el primero y el timer
                // se limpia para no dejar trabajo colgando.
                const terminar = (res) => {
                    if (listo) return;
                    listo = true;
                    if (safety) clearTimeout(safety);
                    resolve(res);
                };
                // Red de seguridad: si el gestor no soporta la opcion
                // `timeout` no dispara ontimeout y la promesa quedaria
                // pendiente para siempre. Preferimos resolver como timeout.
                try {
                    safety = setTimeout(() => terminar({ ok: false, status: 0, texto: '', red: true, timeout: true }), timeoutMs + 2000);
                } catch (_) { safety = null; }
                try {
                    gm({
                        method: metodo,
                        url: url,
                        headers: headers,
                        data: body,
                        timeout: timeoutMs,
                        onload: (r) => terminar({
                            ok: r.status >= 200 && r.status < 300,
                            status: r.status,
                            texto: r.responseText || ''
                        }),
                        onerror: () => terminar({ ok: false, status: 0, texto: '', red: true }),
                        ontimeout: () => terminar({ ok: false, status: 0, texto: '', red: true, timeout: true })
                    });
                } catch (e) {
                    terminar({ ok: false, status: 0, texto: String((e && e.message) || e), red: true });
                }
            });
        }
        if (typeof fetch !== 'function') {
            return Promise.resolve({ ok: false, status: 0, texto: 'fetch no disponible', red: true });
        }
        const ctrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
        const timer = ctrl ? setTimeout(() => ctrl.abort(), timeoutMs) : null;
        let peticion;
        try {
            // fetch() lanza SINCRONAMENTE ante una URL malformada o un scheme
            // no soportado. Sin este try/catch el throw escaparia de
            // httpRequest y romperia a quien hace `await httpRequest(...)`.
            peticion = fetch(url, {
                method: metodo,
                headers: headers,
                body: body,
                signal: ctrl ? ctrl.signal : undefined
            });
        } catch (e) {
            if (timer) clearTimeout(timer);
            return Promise.resolve({ ok: false, status: 0, texto: String((e && e.message) || e), red: true });
        }
        return peticion.then((r) => r.text().then((t) => {
            if (timer) clearTimeout(timer);
            return { ok: r.ok, status: r.status, texto: t };
        })).catch((e) => {
            if (timer) clearTimeout(timer);
            return { ok: false, status: 0, texto: String((e && e.message) || e), red: true };
        });
    }

    /* ====================== MIGRACION DESDE HJP WIALON ======================
     * Rondo es un proyecto nuevo (namespace/nombre distinto). Para que los
     * usuarios existentes conserven su configuracion, lista vigilada, rutas,
     * odometro y perfiles, copiamos las claves antiguas hjp.api.* -> rondo.api.*
     * y hjp.api.s.* -> rondo.api.s.* la primera vez que arranca el script.
     * COPIAMOS, no movemos: asi el script "HJP · Wialon" (si alguien conserva
     * la version anterior instalada) sigue funcionando con sus propios datos.
     * La marca de migracion evita repetir el trabajo en arranques sucesivos.
     */
    (function migrarDesdeHjp() {
        try {
            if (window.localStorage.getItem('rondo.api.migrated')) return;
            const pares = [
                ['hjp.api.cfg',      'rondo.api.cfg'],
                ['hjp.api.watch',    'rondo.api.watch'],
                ['hjp.api.memo',     'rondo.api.memo'],
                ['hjp.api.dismissed','rondo.api.dismissed'],
                ['hjp.api.hist',     'rondo.api.hist'],
                ['hjp.api.geo',      'rondo.api.geo'],
                ['hjp.api.barra',    'rondo.api.barra'],
                ['hjp.api.panelsize','rondo.api.panelsize'],
                ['hjp.api.nmolestar','rondo.api.nmolestar'],
                ['hjp.api.limites',  'rondo.api.limites'],
                ['hjp.api.perfiles', 'rondo.api.perfiles'],
                ['hjp.api.filtEstado','rondo.api.filtEstado'],
                ['hjp.api.sortCol',  'rondo.api.sortCol'],
                ['hjp.api.sortDir',  'rondo.api.sortDir'],
                ['hjp.api.rutas',    'rondo.api.rutas'],
                ['hjp.api.odometro', 'rondo.api.odometro'],
                ['hjp.api.s.watch',  'rondo.api.s.watch'],
                ['hjp.api.s.memo',   'rondo.api.s.memo'],
                ['hjp.api.s.dismissed','rondo.api.s.dismissed'],
                ['hjp.api.s.hist',   'rondo.api.s.hist'],
                ['hjp.api.s.geo',    'rondo.api.s.geo'],
                ['hjp.api.s.seleccion','rondo.api.s.seleccion'],
                ['hjp.api.s.kpi',    'rondo.api.s.kpi'],
                ['hjp.api.s.limites', 'rondo.api.s.limites'],
                ['hjp.api.s.orden',  'rondo.api.s.orden'],
                ['hjp.api.s.viajes', 'rondo.api.s.viajes'],
                ['hjp.api.s.filtEstado','rondo.api.s.filtEstado']
            ];
            for (let i = 0; i < pares.length; i++) {
                const from = pares[i][0], to = pares[i][1];
                const v = window.localStorage.getItem(from);
                if (v == null) continue;
                if (window.localStorage.getItem(to) == null) window.localStorage.setItem(to, v);
                // No borramos la clave antigua para no romper la version vieja.
            }
            window.localStorage.setItem('rondo.api.migrated', '1');
        } catch (_) { /* sin localStorage o bloqueado: continuar */ }
    })();

